-- Select your database and schema before running. All identities are synthetic demo records.

CREATE TABLE IF NOT EXISTS VEHICLE_KNOWLEDGE (VEHICLE_ID VARCHAR NOT NULL, DOCUMENT VARIANT NOT NULL, UPDATED_AT TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP());

MERGE INTO VEHICLE_KNOWLEDGE t USING (SELECT 'camry-2022-se' AS VEHICLE_ID, PARSE_JSON('{"vehicleId":"camry-2022-se","make":"Toyota","model":"Camry","year":2022,"trim":"SE","powertrain":"gas","matchStatus":"representative","identitySource":"synthetic","specs":{"seats":{"value":5,"source":"synthetic","reference":"Paarth-approved synthetic camry-2022-se demo assumptions, 2026-10-24; data/SYNTHETIC-DATA.md and data/specs.ts; not verified Toyota specifications"},"cargoCuFt":{"value":15,"source":"synthetic","reference":"Paarth-approved synthetic camry-2022-se demo assumptions, 2026-10-24; data/SYNTHETIC-DATA.md and data/specs.ts; not verified Toyota specifications"},"mpgCombined":{"value":32,"source":"sourced","reference":"EPA/DOE fueleconomy.gov vehicle 44348; https://www.fueleconomy.gov/ws/rest/vehicle/44348; saved data/fixtures/epa.json, fetched 2026-10-24"},"msrp":{"value":28000,"source":"synthetic","reference":"Paarth-approved synthetic camry-2022-se demo assumptions, 2026-10-24; data/SYNTHETIC-DATA.md and data/specs.ts; not verified Toyota specifications"}},"fitStatus":"Physical car-seat and packing fit need verification"}') AS DOCUMENT) s ON t.VEHICLE_ID = s.VEHICLE_ID WHEN MATCHED THEN UPDATE SET DOCUMENT = s.DOCUMENT, UPDATED_AT = CURRENT_TIMESTAMP() WHEN NOT MATCHED THEN INSERT (VEHICLE_ID, DOCUMENT) VALUES (s.VEHICLE_ID, s.DOCUMENT);

MERGE INTO VEHICLE_KNOWLEDGE t USING (SELECT 'rav4-2024-hybrid-xle' AS VEHICLE_ID, PARSE_JSON('{"vehicleId":"rav4-2024-hybrid-xle","make":"Toyota","model":"RAV4","year":2024,"trim":"Hybrid XLE","powertrain":"hybrid","matchStatus":"representative","identitySource":"synthetic","specs":{"seats":{"value":5,"source":"synthetic","reference":"Paarth-approved synthetic rav4-2024-hybrid-xle demo assumptions, 2026-10-24; data/SYNTHETIC-DATA.md and data/specs.ts; not verified Toyota specifications"},"cargoCuFt":{"value":37,"source":"synthetic","reference":"Paarth-approved synthetic rav4-2024-hybrid-xle demo assumptions, 2026-10-24; data/SYNTHETIC-DATA.md and data/specs.ts; not verified Toyota specifications"},"mpgCombined":{"value":39,"source":"sourced","reference":"EPA/DOE fueleconomy.gov vehicle 47392; https://www.fueleconomy.gov/ws/rest/vehicle/47392; saved data/fixtures/epa.json, fetched 2026-10-24"},"msrp":{"value":33000,"source":"synthetic","reference":"Paarth-approved synthetic rav4-2024-hybrid-xle demo assumptions, 2026-10-24; data/SYNTHETIC-DATA.md and data/specs.ts; not verified Toyota specifications"}},"fitStatus":"Physical car-seat and packing fit need verification"}') AS DOCUMENT) s ON t.VEHICLE_ID = s.VEHICLE_ID WHEN MATCHED THEN UPDATE SET DOCUMENT = s.DOCUMENT, UPDATED_AT = CURRENT_TIMESTAMP() WHEN NOT MATCHED THEN INSERT (VEHICLE_ID, DOCUMENT) VALUES (s.VEHICLE_ID, s.DOCUMENT);
